export type ScoreError = "malformed" | "invalid_score" | "duplicate_name";

export type ScoreResult =
  | { readonly kind: "accepted"; readonly scores: ReadonlyMap<string, bigint> }
  | { readonly kind: "rejected"; readonly line: bigint; readonly error: ScoreError };

export function parseScores(lines: readonly string[]): ScoreResult {
  const scores = new Map<string, bigint>();
  const minimum = -9223372036854775808n;
  const maximum = 9223372036854775807n;
  const canonicalScore = /^(?:0|-?[1-9][0-9]*)$/;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const separator = line.indexOf("=");

    if (
      separator <= 0 ||
      line.indexOf("=", separator + 1) !== -1
    ) {
      return { kind: "rejected", line: BigInt(index), error: "malformed" };
    }

    const name = line.slice(0, separator);
    const scoreText = line.slice(separator + 1);

    if (!canonicalScore.test(scoreText)) {
      return {
        kind: "rejected",
        line: BigInt(index),
        error: "invalid_score",
      };
    }

    const score = BigInt(scoreText);

    if (
      score < minimum ||
      score > maximum ||
      score.toString() !== scoreText
    ) {
      return {
        kind: "rejected",
        line: BigInt(index),
        error: "invalid_score",
      };
    }

    if (scores.has(name)) {
      return {
        kind: "rejected",
        line: BigInt(index),
        error: "duplicate_name",
      };
    }

    scores.set(name, score);
  }

  return { kind: "accepted", scores };
}

