package benchmark

import "strconv"

type ScoreError int

const (
	Malformed ScoreError = iota
	InvalidScore
	DuplicateName
)

type ScoreResult interface{ isScoreResult() }

type ParsedScores struct {
	Scores map[string]int64
}

type ScoreFailure struct {
	Line  int64
	Error ScoreError
}

func (ParsedScores) isScoreResult() {}
func (ScoreFailure) isScoreResult() {}

func ParseScores(lines []string) ScoreResult {
	scores := make(map[string]int64, len(lines))

	for index, line := range lines {
		separator := -1
		for position, character := range line {
			if character == '=' {
				if separator != -1 {
					return ScoreFailure{Line: int64(index), Error: Malformed}
				}
				separator = position
			}
		}

		if separator <= 0 {
			return ScoreFailure{Line: int64(index), Error: Malformed}
		}

		name := line[:separator]
		scoreText := line[separator+1:]

		score, err := strconv.ParseInt(scoreText, 10, 64)
		if err != nil || strconv.FormatInt(score, 10) != scoreText {
			return ScoreFailure{Line: int64(index), Error: InvalidScore}
		}

		if _, exists := scores[name]; exists {
			return ScoreFailure{Line: int64(index), Error: DuplicateName}
		}

		scores[name] = score
	}

	return ParsedScores{Scores: scores}
}

