package benchmark

func BoundedWeightedSum(values []int64, cap int64) int64 {
	var sum int64

	for i, value := range values {
		if value > cap {
			value = cap
		} else if value < -cap {
			value = -cap
		}
		sum += value * int64(i+1)
	}

	return sum
}

