export type ScoreError = "malformed" | "invalid_score" | "duplicate_name";

export type ScoreResult =
  | {
      readonly kind: "accepted";
      readonly scores: ReadonlyMap<string, bigint>;
    }
  | {
      readonly kind: "rejected";
      readonly line: bigint;
      readonly error: ScoreError;
    };

type ParsedScore =
  | { readonly kind: "valid"; readonly value: bigint }
  | { readonly kind: "invalid" };

function parseScore(text: string): ParsedScore {
  if (!/^(?:0|-[1-9][0-9]*|[1-9][0-9]*)$/.test(text)) {
    return { kind: "invalid" };
  }

  const value = BigInt(text);
  const minimum = -9223372036854775808n;
  const maximum = 9223372036854775807n;

  if (value < minimum || value > maximum || value.toString() !== text) {
    return { kind: "invalid" };
  }

  return { kind: "valid", value };
}

export function parseScores(lines: readonly string[]): ScoreResult {
  const scores = new Map<string, bigint>();
  let line = 0n;

  for (const entry of lines) {
    const separator = entry.indexOf("=");

    if (
      separator <= 0 ||
      separator !== entry.lastIndexOf("=") ||
      separator === entry.length - 1
    ) {
      return { kind: "rejected", line, error: "malformed" };
    }

    const name = entry.slice(0, separator);
    const parsed = parseScore(entry.slice(separator + 1));

    switch (parsed.kind) {
      case "invalid":
        return { kind: "rejected", line, error: "invalid_score" };
      case "valid":
        if (scores.has(name)) {
          return { kind: "rejected", line, error: "duplicate_name" };
        }
        scores.set(name, parsed.value);
        break;
    }

    line += 1n;
  }

  return { kind: "accepted", scores };
}

