#[derive(Debug, PartialEq, Eq)]
pub enum ScoreError {
    Malformed,
    InvalidScore,
    DuplicateName,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ScoreResult {
    Parsed(std::collections::BTreeMap<String, i64>),
    Failure { line: i64, error: ScoreError },
}

pub fn parse_scores(lines: Vec<String>) -> ScoreResult {
    let mut scores = std::collections::BTreeMap::new();

    for (index, line) in lines.into_iter().enumerate() {
        let line_number = match i64::try_from(index) {
            Ok(value) => value,
            Err(_) => return ScoreResult::Failure {
                line: i64::MAX,
                error: ScoreError::Malformed,
            },
        };

        let (name, score_text) = match line.split_once('=') {
            Some(parts) => parts,
            None => {
                return ScoreResult::Failure {
                    line: line_number,
                    error: ScoreError::Malformed,
                };
            }
        };

        if name.is_empty() || score_text.contains('=') {
            return ScoreResult::Failure {
                line: line_number,
                error: ScoreError::Malformed,
            };
        }

        let score = match score_text.parse::<i64>() {
            Ok(value) => value,
            Err(_) => {
                return ScoreResult::Failure {
                    line: line_number,
                    error: ScoreError::InvalidScore,
                };
            }
        };

        if score_text != score.to_string() {
            return ScoreResult::Failure {
                line: line_number,
                error: ScoreError::InvalidScore,
            };
        }

        match scores.entry(name.to_owned()) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(score);
            }
            std::collections::btree_map::Entry::Occupied(_) => {
                return ScoreResult::Failure {
                    line: line_number,
                    error: ScoreError::DuplicateName,
                };
            }
        }
    }

    ScoreResult::Parsed(scores)
}

