	current := Interval{
		Start: intervals[0].Start,
		End:   intervals[0].End,
	}

	for _, interval := range intervals[1:] {
		if interval.Start <= current.End {
			if interval.End > current.End {
				current.End = interval.End
			}
		} else {
			merged = append(merged, current)
			current = Interval{
				Start: interval.Start,
				End:   interval.End,
			}
		}
	}

