export function boundedWeightedSum(values: readonly bigint[], cap: bigint): bigint {
  let sum = 0n;
  let weight = 1n;

  for (const value of values) {
    let clamped: bigint;

    if (value < -cap) {
      clamped = -cap;
    } else if (value > cap) {
      clamped = cap;
    } else {
      clamped = value;
    }

    sum += clamped * weight;
    weight += 1n;
  }

  return sum;
}

