#[derive(Debug, PartialEq, Eq)]
pub enum ScoreError {
    Malformed,
    InvalidScore,
    DuplicateName,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ScoreResult {
    Parsed(std::collections::BTreeMap<String, i64>),
    Failure { line: i64, error: ScoreError },
}

fn parse_shape(line: String) -> Result<(String, String), ScoreError> {
    let first = line.find('=');
    let last = line.rfind('=');

    match (first, last) {
        (None, None) => Err(ScoreError::Malformed),
        (Some(_), None) => Err(ScoreError::Malformed),
        (None, Some(_)) => Err(ScoreError::Malformed),
        (Some(first_index), Some(last_index)) => {
            if first_index != last_index {
                Err(ScoreError::Malformed)
            } else {
                let name = &line[..first_index];
                let score = &line[first_index + 1..];

                if name.is_empty() {
                    Err(ScoreError::Malformed)
                } else {
                    Ok((name.to_owned(), score.to_owned()))
                }
            }
        }
    }
}

pub fn parse_scores(lines: Vec<String>) -> ScoreResult {
    let mut scores = std::collections::BTreeMap::new();

    for (line_index, line) in lines.into_iter().enumerate() {
        let parsed_shape = parse_shape(line);

        match parsed_shape {
            Err(error) => {
                return ScoreResult::Failure {
                    line: line_index as i64,
                    error,
                };
            }
            Ok((name, score_text)) => {
                let parsed_score = score_text.parse::<i64>();

                match parsed_score {
                    Err(_) => {
                        return ScoreResult::Failure {
                            line: line_index as i64,
                            error: ScoreError::InvalidScore,
                        };
                    }
                    Ok(score) => {
                        if score.to_string() != score_text {
                            return ScoreResult::Failure {
                                line: line_index as i64,
                                error: ScoreError::InvalidScore,
                            };
                        }

                        if scores.contains_key(&name) {
                            return ScoreResult::Failure {
                                line: line_index as i64,
                                error: ScoreError::DuplicateName,
                            };
                        }

                        scores.insert(name, score);
                    }
                }
            }
        }
    }

    ScoreResult::Parsed(scores)
}

