export type InventoryEvent =
  | {
      readonly kind: "stock";
      readonly sku: string;
      readonly quantity: bigint;
    }
  | {
      readonly kind: "sale";
      readonly sku: string;
      readonly quantity: bigint;
    };

export type InventoryResult =
  | {
      readonly kind: "accepted";
      readonly balances: ReadonlyMap<string, bigint>;
    }
  | {
      readonly kind: "rejected";
      readonly index: bigint;
      readonly sku: string;
    };

export function applyInventory(
  events: readonly InventoryEvent[],
): InventoryResult {
  const balances = new Map<string, bigint>();

  for (let index = 0; index < events.length; index += 1) {
    const event = events[index];

    switch (event.kind) {
      case "stock": {
        if (event.quantity <= 0n) {
          return {
            kind: "rejected",
            index: BigInt(index),
            sku: event.sku,
          };
        }

        const balance = balances.get(event.sku) ?? 0n;
        balances.set(event.sku, balance + event.quantity);
        break;
      }
      case "sale": {
        if (event.quantity <= 0n) {
          return {
            kind: "rejected",
            index: BigInt(index),
            sku: event.sku,
          };
        }

        const balance = balances.get(event.sku) ?? 0n;
        if (event.quantity > balance) {
          return {
            kind: "rejected",
            index: BigInt(index),
            sku: event.sku,
          };
        }

        balances.set(event.sku, balance - event.quantity);
        break;
      }
    }
  }

  return {
    kind: "accepted",
    balances,
  };
}

