export type Interval = { readonly start: bigint; readonly end: bigint };

export function mergeSortedIntervals(
  intervals: readonly Interval[],
): readonly Interval[] {
  const merged: Interval[] = [];
  let current: Interval | undefined;

  for (const interval of intervals) {
    if (current === undefined) {
      current = { start: interval.start, end: interval.end };
    } else if (interval.start <= current.end) {
      current = {
        start: current.start,
        end: interval.end > current.end ? interval.end : current.end,
      };
    } else {
      merged.push(current);
      current = { start: interval.start, end: interval.end };
    }
  }

  if (current !== undefined) {
    merged.push(current);
  }

  return merged;
}

