package benchmark

type InventoryEvent interface{ isInventoryEvent() }

type Stock struct {
	SKU      string
	Quantity int64
}

type Sale struct {
	SKU      string
	Quantity int64
}

func (Stock) isInventoryEvent() {}
func (Sale) isInventoryEvent()  {}

type InventoryResult interface{ isInventoryResult() }

type Accepted struct {
	Balances map[string]int64
}

type Rejected struct {
	Index int64
	SKU   string
}

func (Accepted) isInventoryResult() {}
func (Rejected) isInventoryResult() {}

func ApplyInventory(events []InventoryEvent) InventoryResult {
	balances := make(map[string]int64)

	for index, event := range events {
		switch typedEvent := event.(type) {
		case Stock:
			if typedEvent.Quantity <= 0 {
				return Rejected{Index: int64(index), SKU: typedEvent.SKU}
			}
			balances[typedEvent.SKU] += typedEvent.Quantity
		case Sale:
			if typedEvent.Quantity <= 0 {
				return Rejected{Index: int64(index), SKU: typedEvent.SKU}
			}
			balance := balances[typedEvent.SKU]
			if balance < typedEvent.Quantity {
				return Rejected{Index: int64(index), SKU: typedEvent.SKU}
			}
			balances[typedEvent.SKU] = balance - typedEvent.Quantity
		}
	}

	return Accepted{Balances: balances}
}

