            return ScoreFailure(index, ScoreError.MALFORMED)

        try:
            score = int(score_text, 10)
        except ValueError:
            return ScoreFailure(index, ScoreError.INVALID_SCORE)

        if (
            score < minimum
            or score > maximum
            or str(score) != score_text
        ):
            return ScoreFailure(index, ScoreError.INVALID_SCORE)

        if name in scores:
            return ScoreFailure(index, ScoreError.DUPLICATE_NAME)

        scores[name] = score

    return ParsedScores(scores)
