export function boundedWeightedSum(
  values: readonly bigint[],
  cap: bigint,
): bigint {
  const clamp = (value: bigint): bigint =>
    value < -cap ? -cap : value > cap ? cap : value;

  return values.reduce(
    (sum: bigint, value: bigint, index: number): bigint =>
      sum + clamp(value) * BigInt(index + 1),
    0n,
  );
}

