		switch event {
		case Submit:
			return Rejected{Error: EventNotAllowed}
		case Pay:
			return Accepted{State: Paid}
		case Ship:
			return Rejected{Error: EventNotAllowed}
		case Cancel:
			return Accepted{State: Cancelled}
		}
	case Paid:
		switch event {
		case Submit:
			return Rejected{Error: EventNotAllowed}
		case Pay:
			return Rejected{Error: EventNotAllowed}
		case Ship:
			return Accepted{State: Shipped}
		case Cancel:
			return Accepted{State: Cancelled}
		}
	case Shipped:
