	switch state := state.(type) {
	case Active:
		return "active"
	case Suspended:
		return "suspended:" + state.Reason
	case Locked:
		return "locked:" + strconv.FormatInt(state.FailedAttempts, 10)
	case Closed:
		return "closed"
	}
	return "closed"
}

func Suspend(state AccountState, reason string) AccountState {
	switch state := state.(type) {
	case Active:
		return Suspended{Reason: reason}
	case Suspended:
		return state
	case Locked:
		return state
	case Closed:
		return state
	}
	return state
}

