type Expr interface{ isExpr() }

type Literal struct{ Value int64 }
type Add struct{ Left, Right Expr }
type Divide struct{ Numerator, Denominator Expr }
type Negate struct{ Inner Expr }

func (Literal) isExpr() {}
func (Add) isExpr()     {}
func (Divide) isExpr()  {}
func (Negate) isExpr()  {}

type EvalResult interface{ isEvalResult() }

type ValueResult struct{ Value int64 }
type DivisionByZero struct{}

func (ValueResult) isEvalResult()   {}
func (DivisionByZero) isEvalResult() {}

func Evaluate(expression Expr) EvalResult {
	var result EvalResult

	switch value := expression.(type) {
	case Literal:
		result = ValueResult{Value: value.Value}

	case Add:
		left := Evaluate(value.Left)
		switch leftResult := left.(type) {
		case ValueResult:
			right := Evaluate(value.Right)
			switch rightResult := right.(type) {
			case ValueResult:
				result = ValueResult{Value: leftResult.Value + rightResult.Value}
			case DivisionByZero:
				result = rightResult
			}
		case DivisionByZero:
			result = leftResult
		}

	case Divide:
		numerator := Evaluate(value.Numerator)
		switch numeratorResult := numerator.(type) {
		case ValueResult:
			denominator := Evaluate(value.Denominator)
			switch denominatorResult := denominator.(type) {
			case ValueResult:
				if denominatorResult.Value == 0 {
					result = DivisionByZero{}
				} else {
					result = ValueResult{Value: numeratorResult.Value / denominatorResult.Value}
				}
			case DivisionByZero:
				result = denominatorResult
			}
		case DivisionByZero:
			result = numeratorResult
		}

	case Negate:
		inner := Evaluate(value.Inner)
		switch innerResult := inner.(type) {
		case ValueResult:
			result = ValueResult{Value: -innerResult.Value}
		case DivisionByZero:
			result = innerResult
		}
	}

	return result
}

